def recover(self) -> str:
    """Read-only triage of the trusted evidence store.

    Returns one of:

    * ``"valid"`` -- every persisted event head is covered by an
      authenticated ``confirmed`` sidecar record, the confirmed
      ledger contains no foreign heads, and the sidecar tip is
      closed;
    * ``"incomplete"`` -- the ledgers agree on every confirmed
      record but the sidecar ends in an unclosed intent or torn
      append (an interrupted commit);
    * ``"invalid"`` -- the sidecar is missing while evidence exists,
      is corrupt or fails MAC verification, disagrees with the
      database, or a database event lacks trusted anchoring.

    The method never creates, modifies or deletes anything. Trusted
    anchoring must be enabled (``integrity_key`` supplied).
    """
    if not self._anchored:
        raise RuntimeError("trusted anchoring is not enabled")

    raw = self._read_sidecar_bytes()
    conn = self._connect()
    try:
        try:
            request_rows = conn.execute(
                "SELECT tenant_id, request_id FROM requests"
            ).fetchall()
            heads_by_request: dict[tuple[str, str], list[str]] = {}
            for tenant_id, request_id in request_rows:
                rows = conn.execute(
                    "SELECT chain_hash FROM status_events "
                    "WHERE tenant_id = ? AND request_id = ? ORDER BY seq",
                    (tenant_id, request_id),
                ).fetchall()
                heads_by_request[(tenant_id, request_id)] = [
                    row[0] for row in rows
                ]
        except sqlite3.Error:
            raise RuntimeError("failed to recover request evidence") from None
    finally:
        self._release(conn)

    if raw is None:
        # Sidecar absent: only an entirely empty database is valid;
        # any pre-existing (e.g. legacy) database lacks anchoring.
        return "valid" if not heads_by_request else "invalid"
    if not raw:
        confirmed: list[str] = []
        dangling = False
    else:
        snapshot = self._sidecar_snapshot()
        if snapshot is None:
            return "invalid"
        confirmed, dangling = snapshot

    all_db_heads: set[str] = set()
    for heads in heads_by_request.values():
        all_db_heads.update(heads)
        own = set(heads)
        if [head for head in confirmed if head in own] != heads:
            return "invalid"
    # Every authenticated confirmed anchor must correspond to a real
    # persisted event: no confirmed-but-absented history.
    if any(head not in all_db_heads for head in confirmed):
        return "invalid"
