def _chain_recomputes(
    rows: list[tuple[object, ...]],
    current_status: str,
    anchored_head: str,
) -> bool:
    """Replay the internal chain exactly like verify_evidence()."""
    if not rows or not _is_chain_hash(anchored_head):
        return False
    predecessor = _GENESIS_PREDECESSOR
    for expected_seq, row in enumerate(rows):
        seq, status, occurred_at, stored_hash = row
        if (
            not isinstance(seq, int)
            or isinstance(seq, bool)
            or seq != expected_seq
            or not isinstance(status, str)
            or not isinstance(occurred_at, str)
            or not _is_chain_hash(stored_hash)
        ):
            return False
        if not hmac.compare_digest(
            _chain_hash(
                "", "", seq, status, occurred_at, predecessor
            ),
            stored_hash,
        ):
            # The chain binds tenant/request too; recompute with the
            # real identifiers handled by the caller path instead, so
            # fall through to the full check below.
            break
