@contextlib.contextmanager
def _anchor_zone(self):
    """Serialize anchor writers across threads and processes.

    The in-process write lock is already held by mutating callers;
    flock additionally orders independent processes so that intent
    and confirmation records from different transactions can never
    interleave in the sidecar. The lock fd is opened without
    ``O_CREAT`` so that rejected calls (replays, illegal transitions,
    validation failures) on a not-yet-anchored store never create the
    sidecar: when the file is absent the caller holds SQLite's
    ``BEGIN IMMEDIATE`` reservation, which already excludes all other
    writers until the transaction resolves.
    """
    if not self._anchored or self._anchor_mem is not None:
        yield
        return
    lock_fd: int | None
    try:
        flags = os.O_RDWR | os.O_APPEND | getattr(os, "O_CLOEXEC", 0)
        lock_fd = os.open(self._anchor_path, flags)
    except FileNotFoundError:
        lock_fd = None
    if lock_fd is not None:
        fcntl.flock(lock_fd, fcntl.LOCK_EX)
    try:
        yield
    finally:
        if lock_fd is not None:
            fcntl.flock(lock_fd, fcntl.LOCK_UN)
            os.close(lock_fd)

